// This is a server-side file and will not be sent to the browser.
// This configures the function to run on Vercel's Edge Runtime.
export const config = {
  runtime: 'edge',
};

// --- Updated Target URL based on API documentation ---
// Added IncludeDirtRims=true to fetch the missing "Dirt" product line.
const DATA_URL = 'https://api.statusfalgar.se/api/Articles?IncludeAlloyRims=true&IncludeSteelRims=true&IncludeDirtRims=true'; 
const USER_AGENT = 'Pimpit-B2B-Catalog-Proxy/1.3'; // Version bump

/**
 * Fetches data from Source 6 using Basic Authentication.
 */
export default async function handler(req: Request): Promise<Response> {
  // Credentials provided by the user.
  const customerId = '5432';
  const token = 'BSzMrDxAzojUYyGVvXZL3G3Bci0d0PsxRXWq';

  // For Basic Auth, credentials must be in the format "username:password" and Base64 encoded.
  // In this API's case, it's "customerId:token".
  const authString = `${customerId}:${token}`;
  const encodedAuth = btoa(authString); // btoa is available in Edge Runtime

  try {
    // Fetch the data using the new Basic Authentication header.
    const dataResponse = await fetch(DATA_URL, {
        headers: {
            'User-Agent': USER_AGENT,
            'Authorization': `Basic ${encodedAuth}`,
        },
        cache: 'no-store',
    });

    if (!dataResponse.ok) {
        const errorBodyText = await dataResponse.text();
        console.error(`Source 6 API Error (Status: ${dataResponse.status}): ${errorBodyText}`);
        throw new Error(`Autorizare eșuată la Sursa 6 (Status: ${dataResponse.status}). Verificați Customer ID și Token.`);
    }

    // Stream the data back to the client.
    const responseHeaders = new Headers();
    responseHeaders.set('Content-Type', dataResponse.headers.get('Content-Type') || 'text/csv; charset=utf-8');
    responseHeaders.set('Cache-Control', 'no-cache, no-store, must-revalidate');

    return new Response(dataResponse.body, {
      headers: responseHeaders,
      status: 200,
    });

  } catch (error) {
    console.error('Eroare în proxy-ul pentru Sursa 6:', error);
    const errorMessage = error instanceof Error ? error.message : 'A apărut o eroare necunoscută.';
    return new Response(
      JSON.stringify({
          error: "Eroare la încărcarea Sursei 6.",
          details: errorMessage
      }),
      { status: 500, headers: { 'Content-Type': 'application/json' } }
    );
  }
}

import { DataSource, Product } from '../types';
import { normalizeProductAttributes } from '../utils/productUtils';

const map = async (data: Product[]): Promise<Product[]> => {
  const initialProducts = data
    .filter(p => {
        // Basic validation
        if (!p || !p['sku'] || String(p['sku']).trim() === '') return false;

        // EXCLUSION: Filter out 'Dirt' brand from Felgeo as requested
        const producer = String(p['producent'] || '').trim().toLowerCase();
        if (producer === 'dirt') return false;

        return true;
    })
    .map(p => {
      // 1. Price Calculation
      const purchasePriceStr = String(p['cena_zakupu_netto_eur'] || '0').replace(',', '.');
      const purchasePrice = parseFloat(purchasePriceStr) || 0;
      // Formula: (((((Pret achizitie * 4) + 70) * 1.21) * 1.35) * 5) / 4
      const calculatedPrice = Math.round((((((purchasePrice * 4) + 70) * 1.21) * 1.35) * 5) / 4);

      // 2. Stock Calculation
      const stockProducer = parseInt(String(p['stan_magazynowy_producenta']).trim(), 10) || 0;
      const stockOwn = parseInt(String(p['stan_magazynowy_własny']).trim(), 10) || 0;
      const totalStock = Math.max(stockProducer, stockOwn);

      // 3. PCD combination
      const pcd1 = String(p['rozstaw'] || '').trim();
      const pcd2 = String(p['rozstaw2'] || '').trim();
      const combinedPcd = [pcd1, pcd2].filter(Boolean).join('/');

      // 4. Image splitting
      const imageUrls = String(p['zdjęcie'] || '')
        .split(',')
        .map(url => url.trim())
        .filter(url => url.startsWith('http'));

      // 5. Map to unified Product structure
      const product: Product = {
        PartNumber: p['sku'],
        Brand: p['producent'],
        Model: p['model'],
        PartDescription: p['nazwa_produktu'],
        Finish: p['kolor'],
        Size: p['średnica'],
        Width: p['szerokość'],
        PCD: combinedPcd,
        Offset: p['et'],
        CB: p['otwór'],
        Stock: totalStock,
        Price: calculatedPrice,
        Weight: p['waga_netto_kg'],
        Load: p['nośność'],
        ProductionMethod: p['technologia_produkcji'], // Custom field
        Concavity: p['wklęsłość'], // Custom field
        ImageUrl: imageUrls[0],
        ImageUrls: imageUrls,
        Source: 'Sursa 4',
        ProductType: 'Jante', // Assuming all are wheels for now
      };

      return product;
    });

    // Normalize product attributes for consistency
    return initialProducts.map(product => normalizeProductAttributes(product));
};

const fetcher = async (): Promise<Response> => {
    const proxyUrl = '/api/felgeo';

    try {
        const response = await fetch(proxyUrl, { cache: 'no-store' });

        if (!response.ok) {
            let errorDetails = `Proxy-ul intern pentru Sursa 4 a eșuat cu status: ${response.status}.`;
            try {
                const errorData = await response.json();
                if (errorData.details) {
                    errorDetails = `Mesaj de la furnizor (Sursa 4): "${errorData.details}"`;
                } else if (errorData.error) {
                    errorDetails = errorData.error;
                }
            } catch (e) {
                errorDetails = `Proxy-ul pentru Sursa 4 a returnat o eroare neașteptată (status ${response.status}).`;
            }
            throw new Error(errorDetails);
        }

        return response;

    } catch (error) {
        console.error("Eroare la încărcarea Sursei 4 prin proxy:", error);
        const message = error instanceof Error ? error.message : 'Eroare necunoscută.';
        throw new Error(`Nu s-a putut încărca Sursa 4. Motiv: ${message}`);
    }
};

