import { useState, useEffect, useRef } from 'react';
import { Product, SourceError } from '../types';
import { allSources } from '../sources';
import { parseXMLData } from '../utils/xmlParser';
import { parseCsvInWorker } from '../utils/csvWorker'; 
import { supabase, checkSupabaseConnection } from '../lib/supabase';
import { mapDbToProduct, mapProductToDb } from '../utils/dbMapper';

export const useProductsData = () => {
  const [products, setProducts] = useState<Product[]>([]);
  const [loading, setLoading] = useState<boolean>(true);
  const [loadingMessage, setLoadingMessage] = useState<string>('');
  const [sourceErrors, setSourceErrors] = useState<SourceError[]>([]);
  const [isUsingDatabase, setIsUsingDatabase] = useState(false);
  const [isSyncing, setIsSyncing] = useState(false);

  // Load products from DB (Fast)
  const loadFromSupabase = async () => {
      try {
          const { count } = await supabase.from('products').select('*', { count: 'exact', head: true });
          const totalRows = count || 0;

          if (totalRows === 0) return false;

          let allDbProducts: Product[] = [];
          const PAGE_SIZE = 1000; 
          let from = 0;
          let hasMore = true;

          setLoadingMessage(`Se încarcă catalogul... (0 din ${totalRows})`);

          while (hasMore) {
              const to = from + PAGE_SIZE - 1;
              const { data, error } = await supabase.from('products').select('*').range(from, to);

              if (error) throw error;

              if (data && data.length > 0) {
                  const mappedBatch = data.map(mapDbToProduct);
                  allDbProducts = allDbProducts.concat(mappedBatch);

                  setProducts(prev => {
                      if (from === 0) return mappedBatch; 
                      return [...prev, ...mappedBatch];
                  });

                  setLoadingMessage(`Se încarcă catalogul... (${allDbProducts.length} din ${totalRows})`);

                  if (data.length < PAGE_SIZE) {
                      hasMore = false;
                  } else {
                      from += PAGE_SIZE;
                  }
              } else {
                  hasMore = false;
              }
          }
          setIsUsingDatabase(true);
          setLoading(false);
          return true;
      } catch (e) {
          console.error("Error loading from Supabase:", e);
          return false;
      }
  };

  const performBackgroundSync = async () => {
      if (isSyncing) return;
      setIsSyncing(true);
      console.log("Starting Background Sync...");

      try {
        const processedProducts: Product[] = [];
        const errors: SourceError[] = [];

        for (const source of allSources) {
            console.log(`Syncing ${source.name}...`);
            try {
                const fetchOptions: RequestInit = { cache: 'no-store' };
                const res = source.fetcher ? await source.fetcher() : await fetch(source.url!, fetchOptions);
                if (!res.ok) throw new Error(`HTTP ${res.status}`);

                let parsedData: any[];
                if (source.type === 'xml') {
                    const text = await res.text();
                    parsedData = parseXMLData(text);
                } else if (source.type === 'json') {
                    parsedData = await res.json();
                } else {
                    let text: string;
                    if (source.parserConfig?.encoding) {
                         const buffer = await res.arrayBuffer();
                         const decoder = new TextDecoder(source.parserConfig.encoding);
                         text = decoder.decode(buffer);
                    } else {
                         text = await res.text();
                    }
                    parsedData = await parseCsvInWorker(text, source.parserConfig);
                }
                const mapped = await source.map(parsedData);
                console.log(`${source.name}: Found ${mapped.length} products.`);
                processedProducts.push(...mapped);
            } catch (e) {
                console.error(`Sync error source ${source.name}`, e);
                errors.push({ name: source.name, message: e instanceof Error ? e.message : 'Eroare necunoscută' });
            }
        }

        setSourceErrors(errors);

        // Lower threshold slightly (8k) to be safe but still protective
        if (processedProducts.length < 8000) {
            console.error(`Safety Abort: Only ${processedProducts.length} products found. Aborting sync to preserve data.`);
            throw new Error("Sincronizare eșuată: Prea puține produse găsite.");
        }

        console.log(`Data sync successful (${processedProducts.length} items). Updating database...`);

        const { error: truncError } = await supabase.rpc('truncate_products');
        if (truncError) throw truncError;

        const dbRows = processedProducts.map(mapProductToDb);
        const BATCH_SIZE = 250; 

        for (let i = 0; i < dbRows.length; i += BATCH_SIZE) {
            const batch = dbRows.slice(i, i + BATCH_SIZE);
            const { error: insError } = await supabase.from('products').insert(batch);
            if (insError) {
                console.error("Batch insert error at index " + i, insError);
            }
        }

        await supabase.from('sync_status').upsert({ id: 1, last_synced_at: new Date().toISOString(), is_syncing: false });

        console.log("Sync finished. Refreshing view...");
        setProducts([]); 
        await loadFromSupabase();

      } catch (e) {
          console.error("Sync Failed", e);
      } finally {
          setIsSyncing(false);
      }
  };

  const initData = async () => {
      setLoading(true);
      const isConnected = await checkSupabaseConnection();

      if (isConnected) {
          const { data: statusData } = await supabase.from('sync_status').select('*').eq('id', 1).single();
          const lastSynced = statusData?.last_synced_at ? new Date(statusData.last_synced_at).getTime() : 0;
          const now = Date.now();
          const hoursSinceSync = (now - lastSynced) / (1000 * 60 * 60);

          const hasData = await loadFromSupabase();

          // Sync if data is older than 2 hours or missing
          if (!hasData || hoursSinceSync > 2) {
              if (!hasData) setLoadingMessage("Se inițializează catalogul pentru prima dată...");
              performBackgroundSync();
          }
      } else {
          setSourceErrors([{ name: 'System', message: 'Nu s-a putut conecta la baza de date.'}]);
          setLoading(false);
      }
  };

  useEffect(() => {
    initData();
  }, []);

  return { 
      products, 
      loading, 
      loadingMessage, 
      sourceErrors, 
      isUsingDatabase,
      isSyncing
  };
};

import { Product } from '../types';

const keysToNormalize: (keyof Product)[] = ['Size', 'Width', 'Offset', 'CB', 'Load', 'Weight'];

/**
 * Helper to get a property from an object regardless of key casing.
 * Useful for CSV/JSON data from various suppliers.
 */
export const getProp = (obj: any, targetKey: string): any => {
  if (!obj) return undefined;
  if (obj[targetKey] !== undefined) return obj[targetKey];

  const lowerTarget = targetKey.toLowerCase();
  const foundKey = Object.keys(obj).find(k => k.toLowerCase() === lowerTarget);
  return foundKey ? obj[foundKey] : undefined;
};

/**
 * Standardizes product attributes to ensure data consistency for filtering.
 */
export const normalizeProductAttributes = (product: Product): Product => {
  const normalizedProduct = { ...product };

  // Trim all string values first 
  for (const key in normalizedProduct) {
    if (typeof normalizedProduct[key] === 'string') {
      normalizedProduct[key] = String(normalizedProduct[key]).trim();
    }
  }

  // Standardize specific numeric-like fields
  for (const key of keysToNormalize) {
    const value = normalizedProduct[key];
    if (typeof value === 'string' && value) {
      let standardizedValue = value;

      const isComplexValue = standardizedValue.includes(',') || 
                             standardizedValue.includes('/') || 
                             standardizedValue.includes(' ') || 
                             /^-?\d+-\d+$/.test(standardizedValue);

      if (!isComplexValue) {
        let numericString = standardizedValue.replace(',', '.');
        const num = parseFloat(numericString);

        if (!isNaN(num)) {
           standardizedValue = String(num);
        }
      }

      normalizedProduct[key] = standardizedValue;
    }
  }

  return normalizedProduct;
};

import { DataSource, Product } from '../types';
import { normalizeProductAttributes, getProp } from '../utils/productUtils';

const map = async (data: any[]): Promise<Product[]> => {
  const initialProducts = data
    .filter(p => p && getProp(p, 'part_number'))
    .map(p => {
      // 1. Price Calculation Logic
      const suggestedPriceEur = parseFloat(String(getProp(p, 'suggested_retail_price') || '0').replace(',', '.')) || 0;
      const yourNetPriceEur = parseFloat(String(getProp(p, 'your_net_price') || '0').replace(',', '.')) || 0;

      let finalPriceRon = 0;
      let srpBasedPriceRon = suggestedPriceEur > 0 && suggestedPriceEur <= 100 ? (suggestedPriceEur + 10) * 5 : suggestedPriceEur * 5;
      const minMarginPriceRon = (yourNetPriceEur * 5) * 1.15;

      finalPriceRon = srpBasedPriceRon > 0 ? Math.max(srpBasedPriceRon, minMarginPriceRon) : minMarginPriceRon;
      const oldPriceRon = suggestedPriceEur > 0 ? suggestedPriceEur * 5 : 0;
      const displayOldPrice = (oldPriceRon > finalPriceRon) ? oldPriceRon : undefined;

      // 2. Image Aggregation
      const imageUrls = [
          getProp(p, 'photo'), getProp(p, 'photo1'), getProp(p, 'photo2'), 
          getProp(p, 'photo3'), getProp(p, 'photo4'), getProp(p, 'photo5')
      ].filter((url): url is string => url && typeof url === 'string' && url.trim().startsWith('http'));

      // 3. Product Type Categorization
      const productType = (getProp(p, 'thickness') || getProp(p, 'thread_size')) ? 'Accesorii' : 'Jante';

