import { mapDbToProduct, mapProductToDb } from '../utils/dbMapper';

export const useProductsData = () => {
  const [products, setProducts] = useState<Product[]>([]);
  const [loading, setLoading] = useState<boolean>(true);
  const [loadingMessage, setLoadingMessage] = useState<string>('');
  const [sourceErrors, setSourceErrors] = useState<SourceError[]>([]);
  const [isUsingDatabase, setIsUsingDatabase] = useState(false);
  const [isSyncing, setIsSyncing] = useState(false);

  const loadFromSupabase = async () => {
      try {
          const { count, error: countError } = await supabase.from('products').select('*', { count: 'exact', head: true });
          if (countError) throw countError;
          const totalRows = count || 0;

          if (totalRows === 0) return false;

          let allDbProducts: Product[] = [];
          const PAGE_SIZE = 1000; 
          let from = 0;
          let hasMore = true;

          setLoadingMessage(`Se încarcă catalogul... (0 din ${totalRows})`);

          while (hasMore) {
              const { data, error } = await supabase.from('products').select('*').range(from, from + PAGE_SIZE - 1).order('brand', { ascending: true });
              if (error) throw error;
              if (data && data.length > 0) {
                  const mappedBatch = data.map(mapDbToProduct);
                  allDbProducts = allDbProducts.concat(mappedBatch);
                  setProducts(prev => from === 0 ? mappedBatch : [...prev, ...mappedBatch]);
                  setLoadingMessage(`Se încarcă catalogul... (${allDbProducts.length} din ${totalRows})`);
                  if (data.length < PAGE_SIZE) hasMore = false;
                  else from += PAGE_SIZE;
              } else hasMore = false;
          }
          setIsUsingDatabase(true);
          setLoading(false);
          return true;
      } catch (e) {
          console.error("Error loading from Supabase:", e);
          return false;
      }
  };

  const performBackgroundSync = async () => {
      if (isSyncing) return;
      setIsSyncing(true);
      const errors: SourceError[] = [];
      const allMappedProducts: Product[] = [];

      for (const source of allSources) {
          try {
              const res = source.fetcher ? await source.fetcher() : await fetch(source.url!, { cache: 'no-store' });
              if (!res.ok) throw new Error(`HTTP ${res.status}`);

              let parsedData: any[];
              if (source.type === 'xml') {
                  parsedData = parseXMLData(await res.text());
              } else if (source.type === 'json') {
                  parsedData = await res.json();
              } else {
                  const text = source.parserConfig?.encoding ? new TextDecoder(source.parserConfig.encoding).decode(await res.arrayBuffer()) : await res.text();
                  parsedData = await parseCsvInWorker(text, source.parserConfig || {});
              }
              const mapped = await source.map(parsedData);
              allMappedProducts.push(...mapped);
              console.log(`Source ${source.name} synced: ${mapped.length} products`);
          } catch (e) {
              console.error(`Sync error: ${source.name}`, e);
              errors.push({ name: source.name, message: e instanceof Error ? e.message : 'Eroare' });
          }
      }

      setSourceErrors(errors);

      if (allMappedProducts.length > 100) { // Safely lowered threshold
          const { error: truncError } = await supabase.rpc('truncate_products');
          if (truncError) console.error("Truncate failed:", truncError);

          const dbRows = allMappedProducts.map(mapProductToDb);
          const BATCH_SIZE = 500; 
          for (let i = 0; i < dbRows.length; i += BATCH_SIZE) {
              await supabase.from('products').insert(dbRows.slice(i, i + BATCH_SIZE));
          }

          await supabase.from('sync_status').upsert({ id: 1, last_synced_at: new Date().toISOString() });
          await loadFromSupabase();
      }
      setIsSyncing(false);
  };

  useEffect(() => {
    const init = async () => {
        const isConnected = await checkSupabaseConnection();
        if (!isConnected) {
            setLoading(false);
            return;
        }
        const { data: status } = await supabase.from('sync_status').select('last_synced_at').eq('id', 1).single();
        const lastSynced = status?.last_synced_at ? new Date(status.last_synced_at).getTime() : 0;
        const needsSync = (Date.now() - lastSynced) > (1000 * 60 * 60 * 2);
        const hasData = await loadFromSupabase();
        if (!hasData || needsSync) performBackgroundSync();
    };
    init();
  }, []);

  return { products, loading, loadingMessage, sourceErrors, isUsingDatabase, isSyncing };
};

import { Product } from '../types';

const keysToNormalize: (keyof Product)[] = ['Size', 'Width', 'Offset', 'CB', 'Load', 'Weight'];

/**
 * Helper to get a property from an object regardless of key casing, spaces or special characters.
 */
export const getProp = (obj: any, targetKey: string): any => {
  if (!obj) return undefined;

  // 1. Direct match
  if (obj[targetKey] !== undefined) return obj[targetKey];

  // 2. Normalized match (lowercase, no spaces)
  const normalize = (s: string) => s.toLowerCase().replace(/[^a-z0-9]/g, '');
  const normalizedTarget = normalize(targetKey);

  const foundKey = Object.keys(obj).find(k => normalize(k) === normalizedTarget);
  return foundKey ? obj[foundKey] : undefined;
};

/**
 * Standardizes product attributes to ensure data consistency for filtering.
 */
export const normalizeProductAttributes = (product: Product): Product => {
  const normalizedProduct = { ...product };

  for (const key in normalizedProduct) {
    if (typeof normalizedProduct[key] === 'string') {
      normalizedProduct[key] = String(normalizedProduct[key]).trim();
    }
  }

  for (const key of keysToNormalize) {
    const value = normalizedProduct[key];
    if (typeof value === 'string' && value) {
      let standardizedValue = value;

      const isComplexValue = standardizedValue.includes(',') || 
                             standardizedValue.includes('/') || 
                             standardizedValue.includes(' ') || 
                             /^-?\d+-\d+$/.test(standardizedValue);

      if (!isComplexValue) {
        let numericString = standardizedValue.replace(',', '.');
        const num = parseFloat(numericString);

        if (!isNaN(num)) {
           standardizedValue = String(num);
        }
      }

      normalizedProduct[key] = standardizedValue;
    }
  }

  return normalizedProduct;
};

/* global importScripts, self */
declare var Papa: any;

export const parseCsvInWorker = (text: string, config: any): Promise<any[]> => {
    return new Promise((resolve, reject) => {
        if (typeof window !== 'undefined' && (window as any).Papa) {
            try {
                const result = internalParseCSV((window as any).Papa, text, config);
                return resolve(result);
            } catch (e) {
                return reject(e);
            }
        }

        const workerBlob = new Blob([`
            importScripts('https://cdnjs.cloudflare.com/ajax/libs/PapaParse/5.4.1/papaparse.min.js');
            self.onmessage = function(e) {
                const { text, config } = e.data;
                try {
                    const result = parseLogic(Papa, text, config);
                    self.postMessage({ success: true, data: result });
                } catch (err) {
                    self.postMessage({ success: false, error: err.message });
                }
            };

            function parseLogic(Papa, text, config) {
                if (text.charCodeAt(0) === 0xFEFF) text = text.slice(1);
                const pConfig = { skipEmptyLines: 'greedy' };
                if (config.delimiter) pConfig.delimiter = config.delimiter;

                const parseResult = Papa.parse(text, pConfig);
                const allRows = parseResult.data;
                if (!allRows || allRows.length === 0) return [];

                // 1. Strict Column Mapping (e.g. Source 4)
                if (config.columnMapping) {
                    const headers = config.columnMapping;
                    return allRows.slice(1).map(row => {
                        const obj = {};
                        headers.forEach((h, i) => { if(h && i < row.length) obj[h] = row[i]; });
                        return obj;
                    }).filter(o => Object.values(o).some(v => v));
                }

                // 2. Header Finding Logic
                let headerIdx = -1;
                if (config.requiredHeaders) {
                    const req = config.requiredHeaders.map(h => h.toLowerCase());
                    headerIdx = allRows.findIndex(row => {
                        const r = row.map(c => String(c || '').toLowerCase().trim());
                        return req.every(h => r.includes(h)) || (req.length > 3 && req.slice(0, 3).every(h => r.includes(h)));
                    });
                }

                if (headerIdx === -1) {
                    const keywords = ['brand', 'sku', 'price', 'pret', 'artnr', 'article'];
                    headerIdx = allRows.findIndex(row => {
                        const r = row.map(c => String(c || '').toLowerCase());
                        return keywords.some(kw => r.some(cell => cell.includes(kw)));
                    });
                }

                if (headerIdx === -1) headerIdx = allRows.findIndex(row => row.length > 3);
                if (headerIdx === -1) headerIdx = 0;

                const headers = allRows[headerIdx].map(h => String(h || '').trim());
                const dataRows = allRows.slice(headerIdx + 1);

                return dataRows.map(row => {
                    const obj = {};
                    headers.forEach((h, i) => { if(h && i < row.length) obj[h] = row[i]; });
                    return obj;
                }).filter(o => Object.values(o).some(v => v));
            }
        `], { type: 'application/javascript' });

        const worker = new Worker(URL.createObjectURL(workerBlob));
        worker.onmessage = (e) => {
            if (e.data.success) resolve(e.data.data);
            else reject(new Error(e.data.error));
            worker.terminate();
        };
        worker.onerror = (err) => {
            reject(err);
            worker.terminate();
        };
        worker.postMessage({ text, config });
    });
};

function internalParseCSV(Papa: any, text: string, config: any) {
    if (text.charCodeAt(0) === 0xFEFF) text = text.slice(1);
    const pConfig: any = { skipEmptyLines: 'greedy' };
    if (config.delimiter) pConfig.delimiter = config.delimiter;

    const parseResult = Papa.parse(text, pConfig);
    const allRows = parseResult.data;
    if (!allRows || allRows.length === 0) return [];

    if (config.columnMapping) {
        const headers = config.columnMapping;
        return allRows.slice(1).map(row => {
            const obj: any = {};
            headers.forEach((h, i) => { if(h && i < row.length) obj[h] = row[i]; });
            return obj;
        }).filter((o: any) => Object.values(o).some(v => v));
    }

    let headerIdx = -1;
    if (config.requiredHeaders) {
        const req = config.requiredHeaders.map((h: string) => h.toLowerCase());
        headerIdx = allRows.findIndex((row: any[]) => {
            const r = row.map(c => String(c || '').toLowerCase().trim());
            return req.every(h => r.includes(h));
        });
    }

    if (headerIdx === -1) {
        const keywords = ['brand', 'sku', 'price', 'pret'];
        headerIdx = allRows.findIndex((row: any[]) => {
            const r = row.map(c => String(c || '').toLowerCase());
            return keywords.some(kw => r.some(cell => cell.includes(kw)));
        });
    }

    if (headerIdx === -1) headerIdx = 0;

    const headers = allRows[headerIdx].map((h: any) => String(h || '').trim());
    return allRows.slice(headerIdx + 1).map((row: any[]) => {
        const obj: any = {};
        headers.forEach((h, i) => { if(h && i < row.length) obj[h] = row[i]; });
        return obj;
    }).filter((o: any) => Object.values(o).some(v => v));
}

import { useState, useEffect } from 'react';
import { Product, SourceError } from '../types';
import { allSources } from '../sources';
import { parseXMLData } from '../utils/xmlParser';
import { parseCsvInWorker } from '../utils/csvWorker'; 
import { supabase, checkSupabaseConnection } from '../lib/supabase';
import { mapDbToProduct, mapProductToDb } from '../utils/dbMapper';

export const useProductsData = () => {
  const [products, setProducts] = useState<Product[]>([]);
  const [loading, setLoading] = useState<boolean>(true);
  const [loadingMessage, setLoadingMessage] = useState<string>('');
  const [sourceErrors, setSourceErrors] = useState<SourceError[]>([]);
  const [isUsingDatabase, setIsUsingDatabase] = useState(false);
  const [isSyncing, setIsSyncing] = useState(false);

  const loadFromSupabase = async () => {
      try {
          const { count, error: countError } = await supabase.from('products').select('*', { count: 'exact', head: true });
          if (countError) throw countError;
          const totalRows = count || 0;

          if (totalRows === 0) return false;

          let allDbProducts: Product[] = [];
          const PAGE_SIZE = 1000; 
          let from = 0;
          let hasMore = true;

          setLoadingMessage(`Se încarcă catalogul... (0 din ${totalRows})`);

          while (hasMore) {
              const { data, error } = await supabase.from('products').select('*').range(from, from + PAGE_SIZE - 1).order('brand', { ascending: true });
              if (error) throw error;
              if (data && data.length > 0) {
                  const mappedBatch = data.map(mapDbToProduct);
                  allDbProducts = allDbProducts.concat(mappedBatch);
                  setProducts(prev => from === 0 ? mappedBatch : [...prev, ...mappedBatch]);
                  setLoadingMessage(`Se încarcă catalogul... (${allDbProducts.length} din ${totalRows})`);
                  if (data.length < PAGE_SIZE) hasMore = false;
                  else from += PAGE_SIZE;
              } else hasMore = false;
          }
          setIsUsingDatabase(true);
          setLoading(false);
          return true;
      } catch (e) {
          console.error("Error loading from Supabase:", e);
          return false;
      }
  };

  const performBackgroundSync = async () => {
      if (isSyncing) return;
      setIsSyncing(true);
      const errors: SourceError[] = [];
      const allMappedProducts: Product[] = [];

      for (const source of allSources) {
          try {
              const res = source.fetcher ? await source.fetcher() : await fetch(source.url!, { cache: 'no-store' });
              if (!res.ok) throw new Error(`HTTP ${res.status}`);

              let parsedData: any[];
              if (source.type === 'xml') {
                  parsedData = parseXMLData(await res.text());
              } else if (source.type === 'json') {
                  parsedData = await res.json();
              } else {
                  const text = source.parserConfig?.encoding ? new TextDecoder(source.parserConfig.encoding).decode(await res.arrayBuffer()) : await res.text();
                  parsedData = await parseCsvInWorker(text, source.parserConfig || {});
              }
              const mapped = await source.map(parsedData);
              allMappedProducts.push(...mapped);
              console.log(`Source ${source.name} synced: ${mapped.length} products`);
          } catch (e) {
              console.error(`Sync error: ${source.name}`, e);
              errors.push({ name: source.name, message: e instanceof Error ? e.message : 'Eroare' });
          }
      }

      setSourceErrors(errors);

      // Only update if we have a significant amount of data to prevent total wipeout on failure
      const { count: currentCount } = await supabase.from('products').select('*', { count: 'exact', head: true });
      const minThreshold = currentCount ? Math.floor(currentCount * 0.5) : 1000;

      if (allMappedProducts.length >= minThreshold) {
          const { error: truncError } = await supabase.rpc('truncate_products');
          if (truncError) console.error("Truncate failed:", truncError);

          const dbRows = allMappedProducts.map(mapProductToDb);
          const BATCH_SIZE = 500; 
          for (let i = 0; i < dbRows.length; i += BATCH_SIZE) {
              await supabase.from('products').insert(dbRows.slice(i, i + BATCH_SIZE));
          }

          await supabase.from('sync_status').upsert({ id: 1, last_synced_at: new Date().toISOString() });
          await loadFromSupabase();
      } else {
          console.warn(`Sync aborted: Only ${allMappedProducts.length} products found. Expected at least ${minThreshold}.`);
      }
      setIsSyncing(false);
  };

  useEffect(() => {
    const init = async () => {
        const isConnected = await checkSupabaseConnection();
        if (!isConnected) {
            setLoading(false);
            return;
        }
        const { data: status } = await supabase.from('sync_status').select('last_synced_at').eq('id', 1).single();
        const lastSynced = status?.last_synced_at ? new Date(status.last_synced_at).getTime() : 0;
        const needsSync = (Date.now() - lastSynced) > (1000 * 60 * 60 * 1); // Every 1h
        const hasData = await loadFromSupabase();
        if (!hasData || needsSync) performBackgroundSync();
    };
    init();
  }, []);

  return { products, loading, loadingMessage, sourceErrors, isUsingDatabase, isSyncing };
};

import { DataSource, Product } from '../types';
import { normalizeProductAttributes, getProp } from '../utils/productUtils';

const map = async (data: any): Promise<Product[]> => {
  const articles = Array.isArray(data) ? data : (data?.Articles || []);
  if (!Array.isArray(articles)) return [];

  const initialProducts = articles
    .filter(p => p && (getProp(p, 'ArticleId') || getProp(p, 'Id')))
    .map(p => {
      const rawPrice = getProp(p, 'NettPrice') || getProp(p, 'Price') || 0;
      const purchasePrice = parseFloat(String(rawPrice).replace(',', '.')) || 0;

      // Formula spec: (((((M cell value *4)+1080)*1.21)*1.4)/4)*0.48
      const calculatedPrice = purchasePrice > 0 
        ? Math.round((((((purchasePrice * 4) + 1080) * 1.21) * 1.4) / 4) * 0.48)
        : 0;

      const numberOfBolts = String(getProp(p, 'Number of bolts') || getProp(p, 'NumberOfBolts') || '').trim();
      const boltCircle = String(getProp(p, 'BoltCirlce') || getProp(p, 'BoltCircle') || '').trim();
      const pcd = (numberOfBolts && boltCircle) ? `${numberOfBolts}x${boltCircle}` : boltCircle;

      const brand = getProp(p, 'Brand Name') || getProp(p, 'BrandName') || 'Unknown Brand';
      const model = getProp(p, 'Model Name') || getProp(p, 'ModelName') || '';
      const imageId = getProp(p, 'ImageId') || getProp(p, 'MainImageId');
      const imageUrl = imageId ? `https://api.statusfalgar.se/api/Images/${imageId}` : undefined;

      const product: Product = {
        PartNumber: getProp(p, 'ArticleId') || getProp(p, 'Id'),
        PartDescription: getProp(p, 'Article Text') || `${brand} ${model}`.trim(),
        Brand: brand,
        Model: model,
        Finish: getProp(p, 'Color') || getProp(p, 'Finish'),
        Width: getProp(p, 'Width'),
        Size: getProp(p, 'Diameter') || getProp(p, 'Size'),
        PCD: pcd,
        Offset: getProp(p, 'offset') || getProp(p, 'ET'),
        CB: getProp(p, 'CenterBore') || getProp(p, 'CH'),
        Load: getProp(p, 'LoadRating') || getProp(p, 'MaxLoad'),
        Stock: parseInt(String(getProp(p, 'QuantityAvailable') || getProp(p, 'Stock') || 0), 10) || 0,
        Price: calculatedPrice,
        ImageUrl: imageUrl,
        ImageUrls: imageUrl ? [imageUrl] : [],
        Source: 'Sursa 6',
        ProductType: 'Jante',
      };

      return product;
    });

    return initialProducts.map(product => normalizeProductAttributes(product));
};

