import { DataSource, Product } from '../types';
import { normalizeProductAttributes, getProp } from '../utils/productUtils';

const map = async (data: any[]): Promise<Product[]> => {
  const initialProducts = data
    .filter(p => p && getProp(p, 'PartNumber') && String(getProp(p, 'PartNumber')).trim() !== '')
    .map(p => {
      // 1. Price Cleaning logic (Handels: "1.200,50", "1200", "1,200.50")
      const priceRaw = getProp(p, 'Pret client in lei/buc') || getProp(p, 'Pret') || '0';
      const priceStr = String(priceRaw).trim();

      let cleanPrice = priceStr;
      // If it has both . and , it's likely 1.200,00
      if (cleanPrice.includes('.') && cleanPrice.includes(',')) {
          cleanPrice = cleanPrice.replace(/\./g, '').replace(',', '.');
      } else if (cleanPrice.includes(',')) {
          // If only comma, could be 1200,50
          cleanPrice = cleanPrice.replace(',', '.');
      }

      const price = parseFloat(cleanPrice.replace(/[^0-9.]/g, '')) || 0;

      // 2. Image Aggregation (Support up to 5 URLs)
      const imageUrls = [
          getProp(p, 'Image URL'), 
          getProp(p, 'Image URL 1'), 
          getProp(p, 'Image URL 2'), 
          getProp(p, 'Image URL 3'), 
          getProp(p, 'Image URL 4')
      ].filter((url): url is string => url && typeof url === 'string' && url.trim().startsWith('http'));

      // 3. Robust Offset (ET) Extraction
      const description = String(getProp(p, 'PartDescription') || '');
      const etInCol = getProp(p, 'Offset') || getProp(p, 'ET');

      let extractedOffset = etInCol;
      if (!extractedOffset || extractedOffset === '#N/A' || extractedOffset === 'all') {
          const etMatch = description.match(/\bET\s?(-?\d+(?:-\d+)?)\b/i);
          extractedOffset = etMatch ? etMatch[1] : undefined;
      }

      // 4. Stock Handling (Specific to Pimpit Sheet)
      const stock = parseInt(String(getProp(p, '7001') || '0').replace(/[^0-9]/g, ''), 10) || 0;
      const onTheWater = parseInt(String(getProp(p, 'On the water') || '0').replace(/[^0-9]/g, ''), 10) || 0;

      const product: Product = {
        PartNumber: getProp(p, 'PartNumber'),
        PartDescription: description,
        Brand: getProp(p, 'Brand'),
        EAN: getProp(p, 'EAN'),
        Model: getProp(p, 'Model'),
        Size: getProp(p, 'Size'),
        Width: getProp(p, 'Width'),
        PCD: getProp(p, 'PCD'),
        CB: getProp(p, 'CB'),
        Finish: getProp(p, 'Finish'),
        Load: getProp(p, 'Load'),
        Weight: getProp(p, 'Weight'),
        Description: getProp(p, 'Description'),
        next_delivery: getProp(p, 'next_delivery'),
        ThreeSixtyImageUrl: getProp(p, 'ThreeSixtyImageUrl'),
        TuvUrl: getProp(p, 'TuvUrl'),
        YoutubeUrl: getProp(p, 'YoutubeUrl'),
        Offset: extractedOffset,
        Price: Math.round(price),
        Stock: stock,
        OnTheWaterStock: onTheWater,
        ImageUrl: imageUrls[0],
        ImageUrls: imageUrls,
        Source: 'Sursa 1',
        ProductType: 'Jante',
      };

      return product;
    });

  return initialProducts.map(product => normalizeProductAttributes(product));
};

