export const checkSupabaseConnection = async () => {
    try {
        // Simple check to see if we can connect to the DB
        const { error } = await supabase.from('products').select('count', { count: 'exact', head: true });

        if (error) {
            // Error code 42P01 means 'undefined_table' (table missing), which technically means connection works
            if (error.code === '42P01') {
                console.warn("Supabase Connected, but 'products' table is missing.");
                return false;
            }
            console.warn("Supabase connection check failed:", error.message);
            return false;
        }
        return true;
    } catch (e) {
        console.error("Supabase connection exception:", e);
        return false;
    }
};

