}

export const supabase = createClient<Database>(supabaseUrl, supabaseAnonKey);

export const checkSupabaseConnection = async (): Promise<{ success: boolean; message: string }> => {
  try {
    const { data, error, status } = await supabase.from('products').select('*').limit(1).head({ head: true });

    if (error) {
      console.error('Supabase connection check failed:', error);

      if (status === 404) {
        return { success: false, message: 'Table "products" not found. Please ensure the table exists in your Supabase database.' };
      }
      if (error.code === '42P01') { // Table doesn't exist
        return { success: false, message: 'Table "products" not found. Please ensure the table exists in your Supabase database.' };
      }
        if (error.code === '42501') { // RLS
          return { success: false, message: 'Supabase RLS is preventing your connection. Please ensure the proper RLS policies are enabled.' };
        }
      return { success: false, message: `Supabase connection failed: ${error.message} (Status: ${status}, Code: ${error.code})` };
    }
    console.log('Supabase connection check successful.');
    return { success: true, message: 'Successfully connected to Supabase.' };
  } catch (err) {
    console.error('Unexpected Supabase connection error:', err);
    return { success: false, message: `Unexpected error: ${err}` };
  }
};
